function renderEnvironmentLeases({ force = false } = {}) {
  const panel = $("environment-leases");
  if (!panel) return;
  if (!force && panel.contains(document.activeElement) && document.activeElement?.matches("input, textarea")) return;
  if (state.environmentLeasesError) { panel.replaceChildren(element("p", "notice error", state.environmentLeasesError)); return; }
  if (!state.environmentLeases) { panel.replaceChildren(element("p", "context-note", "正在读取环境占用…")); return; }
  const fragment = document.createDocumentFragment();
  const cleanupLabels = { NOT_REQUIRED: "无需清理", SUCCEEDED: "清理完成", UNKNOWN: "清理结果未知", FAILED: "清理失败" };
  for (const lease of state.environmentLeases.items) {
    const card = element("section", "environment-lease-card");
    card.append(element("h3", "", lease.origin), element("p", "", `${lease.audit_name} · ${lease.audit_id}`));
    card.append(element("p", "context-note", `占用开始：${formatDate(lease.acquired_at)} · ${cleanupLabels[lease.cleanup_status] ?? lease.cleanup_status}`), element("p", "", lease.message));
    const reasonLabels = { "runtime-packet-timed-out": "动态测试超时", PROCESS_RECOVERY_ENVIRONMENT_UNKNOWN: "任务中断后无法确认环境状态", BROWSER_CLOSE_FAILED: "测试浏览器未能正常关闭", USER_CANCELLED: "测试被取消" };
    if (lease.runtime_reason) card.append(element("p", "context-note", `原任务动态阶段：${reasonLabels[lease.runtime_reason] ?? lease.runtime_reason}`));
    const source = element("button", "text-button", "查看原任务");
    source.addEventListener("click", () => selectAudit(lease.audit_id).catch(showError)); card.append(source);
    if (lease.can_release && state.runtime?.runner?.enabled) {
      const details = element("details", "environment-lease-review"); details.append(element("summary", "", "核对并解除占用"));
      const form = element("form");
      const draftKey = `${lease.id}:${lease.revision}`;
      const draft = state.environmentLeaseDrafts.get(draftKey) ?? { note: "", reviewed: false };
      const label = element("label", "", "核对说明"); const note = element("textarea");
      note.required = true; note.maxLength = 2000; note.rows = 3; note.placeholder = "例如：原任务已停止，已复核测试操作或完成环境重置。请勿填写账号、口令。";
      label.append(note);
      const confirmation = element("label", "environment-lease-confirm"); const checkbox = element("input"); checkbox.type = "checkbox"; checkbox.required = true;
      note.value = draft.note; checkbox.checked = draft.reviewed;
      const saveDraft = () => state.environmentLeaseDrafts.set(draftKey, { note: note.value, reviewed: checkbox.checked });
      note.addEventListener("input", saveDraft); checkbox.addEventListener("change", saveDraft);
      confirmation.append(checkbox, element("span", "", "已核对原任务，确认此环境可供新任务使用"));
      const result = element("p", "context-note"); result.setAttribute("role", "status");
      const submit = element("button", "button secondary", "解除占用"); submit.type = "submit";
      form.append(label, confirmation, element("p", "context-note", "解除操作会存档核对说明，保留旧任务的失败和清理记录；不会自动启动测试。"), submit, result);
      form.addEventListener("submit", async event => {
        event.preventDefault(); submit.disabled = true; result.textContent = "正在解除占用…";
        try {
          await api(`/api/v1/runtime-environment-leases/${lease.id}/release`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision: lease.revision, reviewed: checkbox.checked, note: note.value }) });
          state.environmentLeaseDrafts.delete(draftKey);
          await loadEnvironmentLeases(); toast("环境占用已解除，可新建任务；旧任务记录已保留。");
        } catch (error) { result.textContent = error.message; }
        finally { submit.disabled = false; }
      });
      details.append(form); card.append(details);
    }
    fragment.append(card);
  }
  if (!state.environmentLeases.items.length) fragment.append(element("p", "context-note", "当前没有被占用的测试环境。"));
  if (state.environmentLeases.history.length) {
    const history = element("details", "environment-lease-history"); history.append(element("summary", "", "最近解除记录"));
    const list = element("ul");
    for (const entry of state.environmentLeases.history) list.append(element("li", "", `${formatDate(entry.released_at)} · ${entry.origin} · ${entry.audit_name} · ${entry.decision === "automatic" ? "自动回收" : "已核对解除"}：${entry.note}`));
    history.append(list); fragment.append(history);
  }
  panel.replaceChildren(fragment);
}

async function loadEnvironmentLeases() {
  try { state.environmentLeases = await api("/api/v1/runtime-environment-leases"); state.environmentLeasesError = null; }
  catch (error) { state.environmentLeasesError = `环境占用读取失败：${error.message}`; }
  if (state.view === "runtime") renderEnvironmentLeases({ force: true });
}

